@page{size:A3 landscape;margin:12mm}
html,body{margin:0!important}body{font-family:Arial,"MS Gothic",sans-serif;font-size:10pt;line-height:1.5;hyphens:none;font-variant-ligatures:none}
h1,h2,h3,h4{break-after:avoid}p{orphans:3;widows:3}
thead{display:table-header-group}tr{break-inside:avoid}
table[data-renderer-markdown]{width:100%;table-layout:auto}
table[data-renderer-markdown] col{width:auto!important}
table[data-renderer-markdown] th,table[data-renderer-markdown] td{overflow-wrap:normal;word-break:normal;vertical-align:top}
table[data-renderer-markdown]:not([data-renderer-columns="1"]):not([data-renderer-columns="2"]) th:first-child,
table[data-renderer-markdown]:not([data-renderer-columns="1"]):not([data-renderer-columns="2"]) td:first-child{white-space:nowrap;min-width:6em}
table[data-renderer-markdown] code{white-space:nowrap}
table[data-renderer-markdown][data-renderer-columns="2"] a{white-space:nowrap}
table[data-renderer-markdown][data-renderer-columns="10"]{font-size:9pt}
table[data-renderer-markdown][data-renderer-columns="10"] code{font-size:inherit}
table[data-renderer-markdown][data-renderer-columns="10"] th,table[data-renderer-markdown][data-renderer-columns="10"] td{padding-left:3px;padding-right:3px}
:not(pre)>code{white-space:nowrap}
body>title{display:block}
form#reportForm.report-filter-form>div.report-filter-grid{display:block}
main.app-shell>section.screen.report-screen>div.screen-header.report-page-header.no-print{display:flex}
main.app-shell>section.screen.report-screen>form#reportForm.report-filter-form.no-print{display:block}
body>div.validation-summary.no-print[role="alert"]{display:block}
section.report-preview-shell[aria-label="印刷プレビュー"]>div.report-preview-toolbar.no-print{display:flex}
pre{white-space:pre-wrap;overflow-wrap:normal;word-break:normal;font-size:9pt;hyphens:none}
img{max-width:100%;height:auto}img[data-renderer-diagram]{max-height:240mm;object-fit:contain;break-inside:avoid}
.pdf-native-tile{break-before:page;break-inside:avoid;margin:0;padding:0}
.pdf-native-tile img{max-width:none;width:auto;height:auto}
.pdf-native-tile figcaption{font-size:9pt;margin:0 0 2mm}

